frappe.ui.form.on("Pricing Rule", {
	refresh(frm) {
		frm.remove_custom_button(__("Share on WhatsApp"));
		if (frm.is_new()) {
			return;
		}

		frm.add_custom_button(__("Share on WhatsApp"), () => open_offer_dialog(frm));
	},
});

function open_offer_dialog(frm) {
	const default_customer = frm.doc.applicable_for === "Customer" ? frm.doc.customer : "";
	let dialog;

	dialog = new frappe.ui.Dialog({
		title: __("Share Offer on WhatsApp"),
		fields: [
			{
				fieldname: "customer",
				label: __("Customer"),
				fieldtype: "Link",
				options: "Customer",
				reqd: 1,
				default: default_customer,
				onchange() {
					const customer = dialog.get_value("customer");
					dialog._customer_request = (dialog._customer_request || 0) + 1;
					dialog._customer_name = customer || "";
					dialog.set_value("whatsapp_number", "");
					if (customer) {
						load_customer_details(dialog, customer, dialog._customer_request);
					}
				},
			},
			{
				fieldname: "whatsapp_number",
				label: __("WhatsApp Number"),
				fieldtype: "Data",
				options: "Phone",
				reqd: 1,
			},
		],
		primary_action_label: __("Open WhatsApp"),
		primary_action(values) {
			const phone = normalize_whatsapp_number(values.whatsapp_number);
			if (!phone) {
				frappe.msgprint({
					title: __("Invalid WhatsApp Number"),
					message: __("Enter a valid WhatsApp number with country code."),
					indicator: "orange",
				});
				return;
			}

			const customer_name = dialog._customer_name || values.customer;
			const message = build_offer_message(frm.doc, customer_name);
			const url = `https://wa.me/${phone}?text=${encodeURIComponent(message)}`;
			const whatsapp_window = window.open(url, "_blank", "noopener,noreferrer");
			if (!whatsapp_window) {
				frappe.msgprint(__("Please allow pop-ups to open WhatsApp."));
				return;
			}
			dialog.hide();
		},
	});

	dialog.show();
	if (default_customer) {
		dialog._customer_request = 1;
		load_customer_details(dialog, default_customer, dialog._customer_request);
	}
}

function load_customer_details(dialog, customer, request_id) {
	frappe.db
		.get_value("Customer", customer, ["customer_name", "mobile_no", "customer_primary_contact"])
		.then((response) => {
			if (request_id !== dialog._customer_request) {
				return;
			}

			const details = response.message || {};
			dialog._customer_name = details.customer_name || customer;
			if (details.mobile_no) {
				dialog.set_value("whatsapp_number", details.mobile_no);
				return;
			}

			if (!details.customer_primary_contact) {
				return;
			}

			return frappe.db
				.get_value("Contact", details.customer_primary_contact, "mobile_no")
				.then((contact_response) => {
					if (request_id !== dialog._customer_request) {
						return;
					}
					const mobile_no = contact_response.message && contact_response.message.mobile_no;
					if (mobile_no) {
						dialog.set_value("whatsapp_number", mobile_no);
					}
				});
		})
		.catch(() => {
			frappe.msgprint(
				__("Unable to retrieve customer contact details. You can enter the number manually.")
			);
		});
}

function normalize_whatsapp_number(value) {
	let phone = String(value || "").replace(/\D/g, "");
	if (phone.startsWith("00")) {
		phone = phone.slice(2);
	}
	if (phone.length === 11 && phone.startsWith("0")) {
		phone = phone.slice(1);
	}
	if (phone.length === 10) {
		phone = `91${phone}`;
	}
	return /^\d{11,15}$/.test(phone) ? phone : "";
}

function build_offer_message(rule, customer_name) {
	const lines = [`Hello ${customer_name},`, "", `Offer: ${rule.title || rule.name}`];

	if (rule.rate_or_discount === "Discount Percentage") {
		lines.push(`Discount: ${rule.discount_percentage || 0}% off`);
	} else if (rule.rate_or_discount === "Discount Amount") {
		lines.push(
			`Discount: ${rule.discount_amount || 0}${rule.currency ? ` ${rule.currency}` : ""}`
		);
	} else {
		lines.push(`Special price: ${rule.rate || 0}${rule.currency ? ` ${rule.currency}` : ""}`);
	}

	const items = (rule.items || []).map((item) => item.item_code).filter(Boolean);
	const item_groups = (rule.item_groups || []).map((group) => group.item_group).filter(Boolean);
	if (items.length) {
		lines.push(`Applicable products: ${items.join(", ")}`);
	}
	if (item_groups.length) {
		lines.push(`Applicable item groups: ${item_groups.join(", ")}`);
	}

	lines.push(
		rule.valid_upto
			? `Valid until: ${frappe.datetime.str_to_user(rule.valid_upto)}`
			: "Valid for a limited period"
	);
	lines.push("", "Please contact us to know more.");
	return lines.join("\n");
}

// ===========================================================================
// Return Reason Popup – Sales Invoice (Client Script)
// App: cloting  |  DocType: Sales Invoice
//
// Strategy:
//   • The standard ERPNext return button uses frappe.model.open_mapped_doc()
//     which calls the server mapper, then navigates to the new draft doc.
//   • When the new return draft loads, frm.doc.is_return == 1 and
//     frm.doc.docstatus == 0 (draft) and frm.doc.__islocal == 1.
//   • We hook the refresh event.  On each refresh we check if this is a
//     return draft that still needs its reason captured.
//   • A session-level flag (frm._return_reason_dialog_shown) prevents the
//     dialog from reopening while the cashier is filling in the form.
//     The flag is cleared when the form reloads from the server (after save),
//     so if the reason was never saved, the dialog reappears on reopening.
// ===========================================================================

frappe.ui.form.on("Sales Invoice", {
	refresh(frm) {
		if (!_should_show_return_reason_dialog(frm)) {
			return;
		}
		// Mark that we have shown the dialog for this in-memory session so
		// repeated refresh calls (triggered by field changes) don't stack dialogs.
		frm._return_reason_dialog_shown = true;
		_show_return_reason_dialog(frm);
	},
});

// ---------------------------------------------------------------------------
// Guard: decide whether the popup should appear right now.
// ---------------------------------------------------------------------------
function _should_show_return_reason_dialog(frm) {
	// Must be a return document.
	if (!frm.doc.is_return) return false;

	// Only show for draft (unsaved / newly mapped) documents.
	if (frm.doc.docstatus !== 0) return false;

	// If the return reason is already filled in, do not show again.
	if (frm.doc.custom_return_reason) return false;

	// Prevent repeated popups within the same form session.
	if (frm._return_reason_dialog_shown) return false;

	return true;
}

// ---------------------------------------------------------------------------
// Dialog builder and submission handler.
// ---------------------------------------------------------------------------
function _show_return_reason_dialog(frm) {
	const REASON_OPTIONS = [
		{ label: __("Size Issue"),    value: "Size Issue" },
		{ label: __("Colour Issue"),  value: "Colour Issue" },
		{ label: __("Defect"),        value: "Defect" },
		{ label: __("Wrong Item"),    value: "Wrong Item" },
		{ label: __("Billing Error"), value: "Billing Error" },
		{ label: __("Changed Mind"),  value: "Changed Mind" },
		{ label: __("Other"),         value: "Other" },
	];

	const dialog = new frappe.ui.Dialog({
		title: __("Return Reason"),
		fields: [
			{
				fieldname: "custom_return_reason",
				label: __("Return Reason"),
				fieldtype: "Select",
				options: REASON_OPTIONS.map((o) => o.value).join("\n"),
				reqd: 1,
				onchange() {
					_toggle_other_reason(dialog);
				},
			},
			{
				fieldname: "custom_other_return_reason",
				label: __("Other Return Reason"),
				fieldtype: "Small Text",
				hidden: 1,
				reqd: 0,
			},
			{
				fieldname: "custom_return_remarks",
				label: __("Return Remarks"),
				fieldtype: "Small Text",
				reqd: 0,
			},
		],
		primary_action_label: __("Continue"),
		primary_action(values) {
			// --- Validation ---
			if (!values.custom_return_reason) {
				frappe.msgprint({
					title: __("Required"),
					message: __("Please select a Return Reason before continuing."),
					indicator: "orange",
				});
				return;
			}
			if (
				values.custom_return_reason === "Other" &&
				!String(values.custom_other_return_reason || "").trim()
			) {
				frappe.msgprint({
					title: __("Required"),
					message: __("Please describe the specific reason in Other Return Reason."),
					indicator: "orange",
				});
				return;
			}

			dialog.hide();

			// --- Apply values to the form ---
			frm.set_value("custom_return_reason", values.custom_return_reason);
			frm.set_value(
				"custom_other_return_reason",
				values.custom_return_reason === "Other"
					? (values.custom_other_return_reason || "").trim()
					: ""
			);
			frm.set_value("custom_return_remarks", (values.custom_return_remarks || "").trim());

			// Save the draft so the values persist when the cashier reviews.
			frm.save("Save").then(() => {
				frm.reload_doc();
			}).catch(() => {
				// Save failed; keep values in the in-memory doc so the cashier
				// can still see them and retry manually.
			});
		},
		secondary_action_label: __("Cancel"),
		secondary_action() {
			dialog.hide();
			// Clear the session flag so the popup can reappear if the cashier
			// navigates away and reopens the document without saving a reason.
			frm._return_reason_dialog_shown = false;
		},
	});

	dialog.show();
}

// ---------------------------------------------------------------------------
// Toggle the Other Return Reason field visibility and mandatory state.
// ---------------------------------------------------------------------------
function _toggle_other_reason(dialog) {
	const reason = dialog.get_value("custom_return_reason");
	const is_other = reason === "Other";

	const other_field = dialog.get_field("custom_other_return_reason");
	if (!other_field) return;

	other_field.df.hidden = is_other ? 0 : 1;
	other_field.df.reqd   = is_other ? 1 : 0;

	if (!is_other) {
		dialog.set_value("custom_other_return_reason", "");
	}

	dialog.refresh();
}

// ===========================================================================
// Return Reason Popup – POS Invoice (Client Script)
// App: cloting  |  DocType: POS Invoice
//
// Identical logic to the Sales Invoice script; maintained separately so each
// DocType's client script bundle is independent and can be enabled/disabled
// individually.
// ===========================================================================

frappe.ui.form.on("POS Invoice", {
	refresh(frm) {
		if (!_should_show_return_reason_dialog(frm)) {
			return;
		}
		frm._return_reason_dialog_shown = true;
		_show_return_reason_dialog(frm);
	},
});

// ---------------------------------------------------------------------------
// Guard: decide whether the popup should appear right now.
// ---------------------------------------------------------------------------
function _should_show_return_reason_dialog(frm) {
	if (!frm.doc.is_return) return false;
	if (frm.doc.docstatus !== 0) return false;
	if (frm.doc.custom_return_reason) return false;
	if (frm._return_reason_dialog_shown) return false;
	return true;
}

// ---------------------------------------------------------------------------
// Dialog builder and submission handler.
// ---------------------------------------------------------------------------
function _show_return_reason_dialog(frm) {
	const dialog = new frappe.ui.Dialog({
		title: __("Return Reason"),
		fields: [
			{
				fieldname: "custom_return_reason",
				label: __("Return Reason"),
				fieldtype: "Select",
				options: "Size Issue\nColour Issue\nDefect\nWrong Item\nBilling Error\nChanged Mind\nOther",
				reqd: 1,
				onchange() {
					_toggle_other_reason(dialog);
				},
			},
			{
				fieldname: "custom_other_return_reason",
				label: __("Other Return Reason"),
				fieldtype: "Small Text",
				hidden: 1,
				reqd: 0,
			},
			{
				fieldname: "custom_return_remarks",
				label: __("Return Remarks"),
				fieldtype: "Small Text",
				reqd: 0,
			},
		],
		primary_action_label: __("Continue"),
		primary_action(values) {
			if (!values.custom_return_reason) {
				frappe.msgprint({
					title: __("Required"),
					message: __("Please select a Return Reason before continuing."),
					indicator: "orange",
				});
				return;
			}
			if (
				values.custom_return_reason === "Other" &&
				!String(values.custom_other_return_reason || "").trim()
			) {
				frappe.msgprint({
					title: __("Required"),
					message: __("Please describe the specific reason in Other Return Reason."),
					indicator: "orange",
				});
				return;
			}

			dialog.hide();

			frm.set_value("custom_return_reason", values.custom_return_reason);
			frm.set_value(
				"custom_other_return_reason",
				values.custom_return_reason === "Other"
					? (values.custom_other_return_reason || "").trim()
					: ""
			);
			frm.set_value("custom_return_remarks", (values.custom_return_remarks || "").trim());

			frm.save("Save").then(() => {
				frm.reload_doc();
			}).catch(() => {
				// Keep values in-memory on failure.
			});
		},
		secondary_action_label: __("Cancel"),
		secondary_action() {
			dialog.hide();
			frm._return_reason_dialog_shown = false;
		},
	});

	dialog.show();
}

// ---------------------------------------------------------------------------
// Toggle the Other Return Reason field visibility and mandatory state.
// ---------------------------------------------------------------------------
function _toggle_other_reason(dialog) {
	const reason = dialog.get_value("custom_return_reason");
	const is_other = reason === "Other";

	const other_field = dialog.get_field("custom_other_return_reason");
	if (!other_field) return;

	other_field.df.hidden = is_other ? 0 : 1;
	other_field.df.reqd   = is_other ? 1 : 0;

	if (!is_other) {
		dialog.set_value("custom_other_return_reason", "");
	}

	dialog.refresh();
}
